create function public.review_pa28_batch4_graph() returns integer
language plpgsql security definer set search_path=pg_catalog,public as $$
declare item jsonb; reference jsonb; v uuid; source_id uuid; model_id uuid; ref_id uuid; model_name text; count_rows integer:=0;
begin
 perform pg_advisory_xact_lock(hashtextextended('review-pa28-batch4',0));
 for item in select value from jsonb_array_elements('[{"type":"AD","number":"2017-14-04","hash":"c4a0414358c58ec17ae2bd52f11b8ec40173795a65a1a8c948ed4f90fd4a43c3","models":["PA-28-140","PA-28-181"],"page":6,"attachment_name":"DRS_2017-14-04.html","excerpt":"Paragraph (c) includes PA-28-140 and PA-28-181, all serial numbers, when one or more installed oil cooler hose assemblies do not meet TSO-C53a Type D.","conditions":{"equipment":"Applicability depends on installed oil cooler hose assemblies. All serial numbers does not mean all aircraft configurations. Hose type, location, age and maintenance history are not recorded in the profile.","compliance":"Page 9 distinguishes Type C replacement/history conditions and Type D terminating conditions. Review the complete AD and aircraft records; no automatic equipment or compliance determination is made."},"references":[{"authority":"FAA","kind":"certificate","key":"AD:95-26-13","label":"AD 95-26-13","relationship":"supersedes","page":6,"excerpt":"Paragraph (b) states that AD 2017-14-04 replaces AD 95-26-13, Amendment 39-9472.","conditions":{"reference_role":"Superseded AD identified in the current original; its full text has not been reviewed here."}},{"authority":"FAA","key":"TSO:C53a","label":"TSO-C53a - fuel and engine oil hose assemblies","page":6,"excerpt":"Paragraph (c) uses TSO-C53a Type D as an equipment applicability condition. Page 9 distinguishes Type C and Type D replacement conditions.","conditions":{"reference_role":"Equipment standard referenced by the AD, with Type C/Type D distinctions. The TSO original has not been retrieved; this edge does not establish approval or installation of any hose."}}]},{"type":"AD","number":"2016-07-21","hash":"c424f034e587ef16ccb1246ef5c0e91ec7d2346d6cce00e7ccf768fadafff56a","models":["PA-28-181"],"page":6,"attachment_name":"DRS_2016-07-21.html","excerpt":"Paragraph (c) lists PA-28-181 newly affected serials 2843021 through 2843768 and previously affected serials 2843769 through 2843775 and 2843779 through 2843791.","conditions":{"serial_ranges":"2843021 through 2843768; 2843769 through 2843775; 2843779 through 2843791.","groups":"Newly affected: 2843021-2843768. Previously affected: 2843769-2843775 and 2843779-2843791. Serials 2843776-2843778 are outside these reviewed intervals. The groups have different compliance provisions.","compliance":"A serial match does not establish completed right-wing rib inspection or corrective work. Paragraph (g) distinguishes group actions and eligible bulletin editions."},"references":[{"authority":"FAA","kind":"certificate","key":"AD:2015-20-13","label":"AD 2015-20-13","relationship":"supersedes","page":6,"excerpt":"Paragraph (b) replaces AD 2015-20-13.","conditions":{"reference_role":"Superseded AD; full original not reviewed in this batch."}},{"authority":"PIPER","key":"SB:1279A:2016-03-03","label":"Piper SB 1279A - March 3, 2016","page":7,"excerpt":"Paragraph (g)(2) specifies SB 1279A for newly affected airplanes. Paragraph (k) incorporates the dated bulletin.","publisher_id":"18760","conditions":{"reference_role":"Review paragraph (g) for the distinction between newly and previously affected aircraft.","publisher_url":"https://s3.amazonaws.com/pipercrm/Solution/18760/SB 1279A.pdf","publisher_sha256":"50358feb4dfdbcec3a587e23fc5fef3744e4c6b60cf876f8a37b9528fb209823","publisher_reviewed_date":"2026-10-14","publisher_edition_note":"March 3, 2016 edition cited by the AD. First-page identity and date checked against the publisher PDF; review the full procedures with the AD."}},{"authority":"PIPER","key":"SB:1279:2015-08-26","label":"Piper SB 1279 - August 26, 2015","page":7,"excerpt":"Paragraph (k) incorporates SB 1279, August 26, 2015. Paragraph (g)(1)(i) on page 6 permits this edition or 1279A for previously affected airplanes.","conditions":{"reference_role":"Conditional edition alternative for the previously affected group; not substituted for 1279A on newly affected airplanes. Bulletin text not retrieved."}}]},{"type":"AD","number":"2004-14-12","hash":"4bc949d5fb8c58e9999e8e33c703c913f05e5c0b934acec63bbaf525234c76ce","models":["PA-28-181"],"page":6,"attachment_name":"DRS_2004-14-12.html","excerpt":"Paragraph (c) lists PA-28-181 Group A serials 2843112 through 2843565 and Group B serials 2843566 through 2843588.","conditions":{"serial_ranges":"2843112 through 2843565; 2843566 through 2843588.","groups":"Group A (2843112-2843565): Part I inspection, subject to the specified prior SB 1139 exception. Groups A and B (Group B: 2843566-2843588): Part II retainer clip action. These are distinct requirements.","publication":"The archived FAA original includes the August 20, 2004 Federal Register correction. That publication date differs from the August 10, 2004 AD effective date.","compliance":"Serial scope does not establish prior work, installed attachment configuration or completed actions. Review paragraph (e) and aircraft records."},"references":[{"authority":"PIPER","key":"SB:1139A:2004-04-09","label":"Piper SB 1139A - April 9, 2004","page":8,"excerpt":"Paragraph (h) incorporates Piper Service Bulletin No. 1139A, April 9, 2004.","publisher_id":"472","conditions":{"publisher_url":"https://s3.amazonaws.com/pipercrm/Solution/472/SB 1139A.pdf","publisher_sha256":"efed467067986cbce0376d420031dcbe003ad27aab1f27e98ff29c0f0c155e55","publisher_reviewed_date":"2026-10-14","publisher_edition_note":"April 9, 2004 edition cited by the AD. First-page identity and date verified; consult both documents for group-specific actions."}},{"authority":"PIPER","key":"SB:1139:2003-08-28","label":"Piper SB 1139 - August 28, 2003","page":7,"excerpt":"Paragraph (e)(1) provides an exception for specified prior actions using SB 1139, August 28, 2003.","conditions":{"reference_role":"Conditional prior-work exception, not a blanket substitute for current required actions. Bulletin text not retrieved."}}]},{"type":"AD","number":"2024-10-04","hash":"db153059646d6ceeb8b85a66be8d9609cf47d6c2c4ef5ed87572dc312e8205d4","models":["PA-28-181"],"page":4,"published_url":"https://www.govinfo.gov/content/pkg/FR-2024-05-22/pdf/2024-11143.pdf","excerpt":"Paragraph (c) includes PA-28-181 with serial numbers identified in Piper Service Bulletin No. 1413, April 9, 2024.","conditions":{"serial_scope":"Serial applicability is delegated to the dated SB 1413. A verified publisher link is available on its reference edge. No automatic serial rule is derived from the external bulletin in this review.","compliance":"The profile does not establish installed rudder configuration, inspection results or completed work. Review the complete AD, cited bulletin and aircraft records.","effective_date":"2024-06-06","publication":"Final published rule, 89 FR 44914-44917, FR document 2024-11143; physical PDF page 4 is printed page 44917."},"references":[{"authority":"PIPER","key":"SB:1413:2024-04-09","label":"Piper SB 1413 - April 9, 2024","page":4,"excerpt":"Paragraph (k)(2)(i) incorporates Piper Service Bulletin No. 1413, dated April 9, 2024.","publisher_id":"20958","conditions":{"source_text":"Publisher PDF retrieved and first-page edition/model table visually checked. This reference does not automatically import its serial list or establish completed procedures.","publisher_url":"https://s3.amazonaws.com/pipercrm/Solution/20958/SB_1413.pdf","publisher_sha256":"928278e80657b05fb3f45a484daef8c9f98721ab7d6b2be2489984abdd0aabb5","publisher_reviewed_date":"2026-10-14","publisher_catalog_date":"2024-04-18","publisher_edition_note":"PDF edition: April 9, 2024, as cited by the AD. Piper catalog release: April 18, 2024. These dates describe different things; the exact reviewed PDF hash is pinned."}}]}]'::jsonb) loop
  select dv.id into v from public.document_versions dv join public.documents d on d.id=dv.document_id
   where d.authority='FAA' and d.document_type=item->>'type' and d.document_number=item->>'number' and dv.content_sha256=item->>'hash'
    and (not (item ? 'published_url') or (dv.metadata->>'original_source_url'=item->>'published_url' and dv.metadata->>'original_source_kind'='final_federal_register'))
    and dv.status='current' and dv.is_published and d.is_published and exists(select 1 from public.related_document_matches match where match.version_id=dv.id and match.is_active) limit 1;
  if v is null then raise exception 'Verified current original or publication provenance missing'; end if;
  insert into public.catalog_entities(authority,entity_type,natural_key,label,is_published) values('FAA','certificate',(item->>'type')||':'||(item->>'number'),(item->>'type')||' '||(item->>'number'),true)
   on conflict(authority,entity_type,natural_key) do update set is_published=true returning id into source_id;
  for model_name in select jsonb_array_elements_text(item->'models') loop
   select id into model_id from public.catalog_entities where authority='FAA' and entity_type='aircraft_model' and natural_key=model_name;
   if model_id is null or not exists(select 1 from public.related_document_matches where version_id=v and model=model_name and is_active) then raise exception 'Current model index missing'; end if;
   insert into public.relationships(source_entity_id,target_entity_id,relationship_type,evidence_version_id,evidence_page,evidence_excerpt,applicability_conditions,review_status,is_published)
    select source_id,model_id,case item->>'type' when 'AD' then 'applies_to' else 'approved_for' end,v,(item->>'page')::integer,item->>'excerpt',(item->'conditions')||coalesce(item->'model_conditions'->model_name,'{}'::jsonb),'reviewed',true
    where not exists(select 1 from public.relationships where source_entity_id=source_id and target_entity_id=model_id and evidence_version_id=v);
   update public.relationships set evidence_page=(item->>'page')::integer,evidence_excerpt=item->>'excerpt',applicability_conditions=(item->'conditions')||coalesce(item->'model_conditions'->model_name,'{}'::jsonb)
    where source_entity_id=source_id and target_entity_id=model_id and evidence_version_id=v and relationship_type=case item->>'type' when 'AD' then 'applies_to' else 'approved_for' end and review_status='reviewed' and is_published;
   count_rows:=count_rows+1;
  end loop;
  for reference in select value from jsonb_array_elements(item->'references') loop
   insert into public.catalog_entities(authority,entity_type,natural_key,label,is_published)
    values(reference->>'authority',coalesce(reference->>'kind','service_document'),reference->>'key',reference->>'label',true)
    on conflict(authority,entity_type,natural_key) do update set is_published=true returning id into ref_id;
   insert into public.relationships(source_entity_id,target_entity_id,relationship_type,evidence_version_id,evidence_page,evidence_excerpt,applicability_conditions,review_status,is_published)
    select source_id,ref_id,coalesce(reference->>'relationship','references'),v,(reference->>'page')::integer,reference->>'excerpt',reference->'conditions','reviewed',true
    where not exists(select 1 from public.relationships where source_entity_id=source_id and target_entity_id=ref_id and evidence_version_id=v and relationship_type=coalesce(reference->>'relationship','references'));
   update public.relationships set evidence_page=(reference->>'page')::integer,evidence_excerpt=reference->>'excerpt',applicability_conditions=reference->'conditions'
    where source_entity_id=source_id and target_entity_id=ref_id and evidence_version_id=v and relationship_type=coalesce(reference->>'relationship','references') and review_status='reviewed' and is_published;
   count_rows:=count_rows+1;
  end loop;
 end loop;
 return count_rows;
end $$;
revoke all on function public.review_pa28_batch4_graph() from public,anon,authenticated;
grant execute on function public.review_pa28_batch4_graph() to service_role;
